"use client"

import * as React from "react"
import { flushSync } from "react-dom"

import { roll } from "@/lib/0db/roll"
import { cn } from "@/lib/utils"

type WordRelayProps = Omit<React.ComponentProps<"button">, "children" | "onChange"> & {
  /** The sentence up to the word that changes: ours, in the roman. */
  children?: React.ReactNode
  /** The words it can end on, in order, each with its own punctuation ("design."). Pressing goes round them. */
  words: readonly string[]
  /** The chosen word's place in `words`, when you hold it (controlled). */
  index?: number
  /** The word to start on, when the relay holds it. */
  defaultIndex?: number
  /** Called with the place of the word the person moved to. */
  onIndexChange?: (index: number) => void
  /** sentence: the word on a hairline at the end of the line. statement: after "It has to be design.", the sentence heavy and
   *  narrow, the word large under it in the italic and the accent, overlapping it. */
  variant?: "sentence" | "statement"
  /** Pins a state for documentation ("hover", "focus"). */
  "data-force"?: string
}

const turn = (i: number, n: number) => ((i % n) + n) % n

/**
 * A sentence whose last word is yours to change. Pressing it, or an arrow key, rolls the word on to the
 * next one (out at the top, in from below; back the other way), and the line narrows or widens to it.
 * The word is set in the expression italic, since it is the one you chose. It never moves by itself.
 */
function WordRelay({ children, words, index, defaultIndex = 0, onIndexChange, variant = "sentence", className, onClick, onKeyDown, "data-force": force, ...props }: WordRelayProps) {
  const n = Math.max(1, words.length)
  const [own, setOwn] = React.useState(defaultIndex)
  const now = turn(index ?? own, n)
  const [shown, setShown] = React.useState(now)
  const way = React.useRef<1 | -1>(1)
  const word = React.useRef<HTMLSpanElement>(null)

  React.useEffect(() => {
    const el = word.current
    if (now === shown || !el) return
    const box = el.parentElement!
    roll(el, () => {
      // The line follows the word: it narrows or widens from the old width to the new one while the word comes in.
      const from = box.offsetWidth
      flushSync(() => setShown(now))
      const to = box.offsetWidth
      if (from !== to && !matchMedia("(prefers-reduced-motion: reduce)").matches)
        box.animate([{ width: `${from}px` }, { width: `${to}px` }], { duration: 320, easing: "cubic-bezier(.65,0,.35,1)" })
    }, "0.7em", way.current)
  }, [now, shown])

  const go = (next: number, dir: 1 | -1) => {
    const to = turn(next, n)
    if (to === now) return
    way.current = dir
    if (index === undefined) setOwn(to)
    onIndexChange?.(to)
  }

  return (
    <button
      type="button"
      data-slot="word-relay"
      data-variant={variant === "sentence" ? undefined : variant}
      data-force={force}
      className={cn("db-relay", className)}
      onClick={(e) => {
        onClick?.(e)
        if (!e.defaultPrevented) go(now + 1, 1)
      }}
      onKeyDown={(e) => {
        onKeyDown?.(e)
        if (e.defaultPrevented) return
        const rtl = getComputedStyle(e.currentTarget).direction === "rtl"
        const k = e.key === "ArrowLeft" && rtl ? "ArrowRight" : e.key === "ArrowRight" && rtl ? "ArrowLeft" : e.key
        if (k === "ArrowDown" || k === "ArrowRight") go(now + 1, 1)
        else if (k === "ArrowUp" || k === "ArrowLeft") go(now - 1, -1)
        else if (k === "Home") go(0, -1)
        else if (k === "End") go(n - 1, 1)
        else return
        e.preventDefault()
      }}
      {...props}
    >
      {children ? <span className="db-relay-lead">{children} </span> : null}
      <span className="db-relay-word" aria-hidden="true">
        <span ref={word}>{words[shown]}</span>
      </span>
      {/* The chosen word for readers: part of the button's name, and read again when it changes. */}
      <span className="db-sr" aria-live="polite">{words[now]}</span>
    </button>
  )
}

export { WordRelay, type WordRelayProps }

@layer components {
  /* ── db-relay ── a sentence whose last word is yours to change: mode-toggle's sentence, for any set of words.
     The lead is ours, in the roman; the word is the one you chose, in the italic, on a hairline that hugs it.
     Pressing rolls the word on (lib/roll.ts) and the hook eases the word's box to its new width. */
  .db-relay {
    appearance: none; border: 0; background: none; padding: 0; margin: 0; font: inherit; letter-spacing: inherit;
    color: var(--db-graphite); text-align: start; cursor: pointer; -webkit-tap-highlight-color: transparent;
    transition: color var(--db-allegro) var(--db-breath);
  }
  .db-relay:is(:hover, [data-force~="hover"]) { color: var(--db-ink); }
  .db-relay:focus-visible, .db-relay[data-force~="focus"] { outline: var(--db-stroke) solid var(--db-accent); outline-offset: 0.12em; }
  .db-relay:disabled { opacity: 0.55; cursor: not-allowed; }
  .db-relay-word {
    display: inline-block; box-sizing: border-box; vertical-align: baseline; overflow: clip; white-space: nowrap;
    padding: 0.12em 0.14em 0.24em; margin-block: -0.12em -0.24em; margin-inline: -0.08em -0.14em;
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1; color: var(--db-ink);
    background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0.14em calc(100% - 0.1em) / calc(100% - 0.28em) var(--db-hairline);
  }
  .db-relay-word > span { display: inline-block; }
  .db-relay:is(:hover, [data-force~="hover"]) .db-relay-word { background-image: linear-gradient(var(--db-ink), var(--db-ink)); }

  /* statement: after "It has to be design.", where heavy narrow roman is answered by a large italic that overlaps it, the one
     accent on the italic word and its full stop. The sentence stands in ink; the word drops under it, half again as large,
     rising into the line above with a halo of the paper round its letters, so it cuts the roman where they cross. */
  .db-relay[data-variant="statement"] { display: inline-grid; justify-items: start; color: var(--db-ink); }
  .db-relay[data-variant="statement"] .db-relay-lead { font-weight: 800; font-stretch: 75%; letter-spacing: -0.035em; line-height: 0.92; }
  .db-relay[data-variant="statement"] .db-relay-word {
    font-size: calc(1.5 * var(--db-expression-scale) * 1em); line-height: 0.9; margin-block: -0.42em -0.24em; margin-inline-start: 0.3em;
    color: var(--db-accent); background-size: 0 var(--db-hairline);
    paint-order: stroke fill; -webkit-text-stroke: 0.06em var(--db-relay-ground, var(--db-paper));
    transition: background-size var(--db-moderato) var(--db-exhale);
  }
  /* Pointing sketches the hairline under the word in pencil: it can be changed. */
  .db-relay[data-variant="statement"]:is(:hover, [data-force~="hover"]) .db-relay-word { background-image: linear-gradient(var(--db-pencil), var(--db-pencil)); background-size: calc(100% - 0.28em) var(--db-hairline); }
  @media (forced-colors: active) {
    .db-relay-word { background-image: linear-gradient(CanvasText, CanvasText); }
    .db-relay[data-variant="statement"] .db-relay-word { color: CanvasText; -webkit-text-stroke: 0; }
  }
}
